"""Primary concentrations only; retain ancillary plant parts with explicit scope decisions."""
import datetime,json,pathlib,re
b=pathlib.Path('data/evidence/contracts/leafy-greens')
inventory=json.load(open(b/'access-inventory.json'))['items'];records=[];reviews=[]
def item(prefix):return next(x for x in inventory if x['source_id'].startswith(prefix))
def locator(i,location):return {'artifact':i['artifact']['path'],'sha256':i['artifact']['sha256'],'kind':'cell','location':location}
i=item('abubakar');codes=['Cd','Co','Pb','Cr','tHg','Cu','Ni']
for vegetable,values,site,species in [('Spinach',[3.58,4.71,6.13,9.43,3.83,3.11,4.77],'Ghulam Muhammad Abad, SiteI','Spinacia oleracea'),('Cauliflower leaves',[3.92,5.55,7.76,5.71,1.94,2.51,2.68],'Chokera, SiteII','Brassica oleracea var. botrytis')]:
 for code,value in zip(codes,values):
  records.append({'id':f'lg-full-abubakar-{vegetable.split()[0].lower()}-{code}','source_id':i['source_id'],'family_id':'abubakar-faisalabad-two-site-survey','analyte':code,'species':species,'material':vegetable+' leaf material','form':'water-washed leaves; dried at60°C for24h before digestion','basis':'Dry weight, based on dried leaf digest; no fresh-weight back-conversion reported','origin_or_market':site+', Faisalabad, Pakistan','year':'Collection date not reported; published2025','n':3,'n_note':'Figure4 gives three replicate measurements; Methods2.2 selects three plants per species at its site. Whether replicate results are independent plant samples or analytical replicates is not specified. Species and site are confounded.','sample_unit':'replicate leaf measurements, independence unresolved','statistic':'reported mean; SD shown graphically only','value_original':value,'unit_original':'mg/kg','value':value*1000,'unit':'µg/kg','sd':None,'censoring':'No per-cell censoring, detection limits or recovery values reported. Graphical SD retained at Figure4, not converted to invented exact numbers.','locator':locator(i,f'PDFp7, printedp52, Results3.5 numeric paragraph and Figure4, {vegetable}, {code}'),'scientific_fit_status':'leaf concentration; cauliflower is explicitly dried leaf material in Methods2.3, not its flower head'})
reviews.append({'source_id':i['source_id'],'identity_verified':True,'completeness_verified':True,'identity_proof':'Complete12-page publisher PDF, printed46–57; matching authors, title and DOI10.54219/arr.03.1.2025.418. Methods2.2–2.3 PDFp3, Results3.5 PDFpp6–7, conclusions/declarations and references throughp12.','artifact':i['artifact'],'extraction_complete':True,'result_ids':[r['id'] for r in records],'decision':'occurrence_extracted','content_scope':'All14 leaf concentrations across two vegetables and seven elements recovered from numeric Results3.5 and verified against Figure4. Soil/water concentrations and plant biomass/pigments/enzymes are distinct context. No matched clean-water control or treatment effect was measured, so species/site difference is not a sewage-removal effect.','limits':'Dried leaf basis. SD is graphical only. Three plant selection and three replicate caption do not establish independent food lot N. Study assertions about WHO limits are not adopted as current compliance or safety conclusions.'})
i=item('joseph');pages=pathlib.Path(i['artifact']['text_path']).read_text().split('\f');allparts=[];codes=['tAs','Fe','Cd','Cu','Cr','Pb','Ni']
for page in [4,5,6]:
 lines=pages[page-1].splitlines()
 for index,line in enumerate(lines):
  label=re.match(r'\s*(Kenaf stem|Kenaf Root|Kenaf leaves|Chili pepper stem|Chili pepper root|Chilipepper leaves|Chili pepper fruits|Tomato stem|Tomato root|Tomato leaves|Tomato fruits|Spinach stem|Spinach root|Spinach leaves)\s+',line)
  if not label:continue
  name=label[1];cells=list(re.finditer(r'(\d+\.\d+)\s*±|B\.D\.L',line[label.end():]));sds=[float(x) for x in re.findall(r'\d+\.\d+',lines[index+1])];assert len(cells)==7,(name,line);assert len(sds)==sum(c[1] is not None for c in cells),(name,sds)
  sdidx=0
  for code,cell in zip(codes,cells):
   value=float(cell[1]) if cell[1] is not None else None;sd=sds[sdidx] if value is not None else None;sdidx+=value is not None
   edible=name in ['Kenaf leaves','Spinach stem','Spinach leaves'];species='Hibiscus cannabinus' if name.startswith('Kenaf') else 'Spinacia oleracea' if name.startswith('Spinach') else 'Solanum lycopersicum' if name.startswith('Tomato') else 'Capsicum annuum'
   r={'id':f'lg-full-joseph-{name.lower().replace(" ","-")}-{code}','source_id':i['source_id'],'family_id':'joseph-gobbiya-dam-survey','analyte':code,'material':name,'species':species,'form':'distilled-water washed; oven-dried80°C24h, powdered before digestion','basis':'Dry weight, dried powder digest; no wet-weight correction reported','origin_or_market':'Gobbiya Dam, Bogoro, Bauchi State, Nigeria','year':'Collection date unreported; publication2025','n':3,'n_note':'Table footnotes n3 mean±SD. Methods2.8 says replicate measurements; independent field specimens/food lot count is not given.','sample_unit':'replicate determinations, field sampling unit unresolved','statistic':'reported mean ± SD','unit_original':'mg/kg','unit':'µg/kg','value_original':value,'sd_original':sd,'value':value*1000 if value is not None else None,'sd':sd*1000 if sd is not None else None,'lower_bound':0 if value is None else None,'upper_bound':None,'censoring':'BDL; numerical food-basis detection limit not supplied; not zero' if value is None else 'Reported quantified mean; food-basis detection limit not supplied','locator':locator(i,f'PDFp{page}, printedp{page+78}, Table'+('1' if name.startswith('Kenaf') else '2' if name.lower().startswith('chili') else '3' if name.startswith('Tomato') else '4')+f', {name}, {code}'),'scientific_fit_status':'leafy vegetable food part' if edible else 'ancillary plant part; not admitted to leafy food occurrence','scope_reason':'Kenaf leaves or spinach edible leaf/stem' if edible else 'Root, fruit or other crop tissue is not a leafy-food observation; tomato/pepper vegetative tissues and kenaf stems lack a demonstrated edible leaf-food role here.'}
   allparts.append(r)
assert len(allparts)==98,len(allparts)
selected=[r for r in allparts if r['scientific_fit_status']=='leafy vegetable food part'];assert len(selected)==21
records+=selected
(b/'joseph-all-plant-parts.json').write_text(json.dumps({'records':allparts,'note':'All98 reported plant-part cells preserved to make scope decisions auditable. Only21 kenaf-leaf/spinach-leaf/stem cells route to leafy-food occurrence; no soil/water/BAF/TF ratios treated as food concentrations.'},indent=2)+'\n')
reviews.append({'source_id':i['source_id'],'identity_verified':True,'completeness_verified':True,'identity_proof':'Complete14-page primary publisher PDF printed79–92; title, Joseph/Buba/Enoch/Kaluri authors and DOI10.37933/jete/7.4.2025.2568 match. Methodspp81–82, allTables1–8 and conclusions/references throughp92.','artifact':i['artifact'],'extraction_complete':True,'decision':'occurrence_extracted','result_ids':[r['id'] for r in selected],'content_scope':'All98 source plant concentration cells recovered in joseph-all-plant-parts.json;21 relevant kenaf-leaf/spinach-leaf/stem cells routed. Other tissues retained with explicit nonleaf scope reasons. Soil/water and BAF/TF/CF/correlations are context, not extra occurrence values or remediation effects. Figures1–4 repeat concentration tables.','limits':'Dry powder basis and n3 replicate measurements, independent field N unknown. Two BDL food cells have no numeric upper bound. Source WHO-labelled benchmarks and statistical tests against fixed limits are not endorsed as current compliance/safety conclusions.'})
for review in reviews:review['reviewed_at']=datetime.datetime.now(datetime.timezone.utc).isoformat()
(b/'recovered-new-primary-batch2.json').write_text(json.dumps({'records':records},indent=2)+'\n')
(b/'primary-reviews-batch2.json').write_text(json.dumps({'reviews':reviews},indent=2)+'\n')
print('Recovered',len(records),'leafy-food concentration records; retained98 Joseph plant-part cells')
